package com.booksyde.controller; import com.booksyde.dto.response.SellerResponse; import com.booksyde.service.SellerService; import java.util.UUID; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/sellers") public class SellerController{private final SellerService service;public SellerController(SellerService s){service=s;}@GetMapping("/me")public SellerResponse me(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){return service.get(UUID.fromString(jwt.getSubject()));}}
